# (category, name, regex on lowercased sentence, position filter, definition, do, dont, test)
C=[]
def a(cat,name,rx,pos,defn,do,dont,test): C.append(dict(id=len(C)+1,cat=cat,name=name,rx=rx,pos=pos,defn=defn,do=do,dont=dont,test=test))
O='open';E='close';M=None
# A. Cold opens & hooks
a('Cold open & hook','Number-first cold open',r'^\$?\d',O,'First lines lead with a hard number or amount.','Open with the single most absurd true number.','Do not open with a vague trend ("AI is changing everything").','Is there a concrete number in the first 2 sentences?')
a('Cold open & hook','Dated-moment cold open',r'\b(?:on|in|for \d+ hours on) (?:(?:mon|tues|wednes|thurs|fri|satur|sun)day|january|february|march|april|may|june|july|august|september|october|november|december|(?:19|20)\d\d)',O,'Open inside a specific dated moment.','Name the day/date and drop the viewer into it.','No "Throughout history..." openings.','Does sentence 1-3 contain a date or day?')
a('Cold open & hook','In-medias-res event open',r'\b(?:just|was caught|had what|began|suddenly|out of nowhere|one guy|someone)\b',O,'Start mid-event, before context.','Start with the event happening, explain later.','Do not start with background or definitions.','Is the first beat an action, not a summary?')
a('Cold open & hook','"What no one is talking about" hook',r'what (?:no one|nobody|most people|people don\'t|you don\'t)',M,'Promise a hidden angle the audience is missing.','Use once in the first minute.','Do not repeat it every section.','Is there one hidden-angle claim near the open?')
a('Cold open & hook','Stakes question hook',r'\?$',O,'A question in the open that the video will answer.','End the cold open with the central question.','No rhetorical questions with obvious answers.','Does the open end on a real question?')
a('Cold open & hook','Viewer-assumption flip',r'\b(?:you might think|you\'d think|most people think|you probably|my first thought|you might have heard)\b',M,'State what the viewer assumes, then flip it.','Voice the viewer\'s first reaction honestly.','Do not strawman the viewer.','Is the assumption one a real viewer would hold?')
a('Cold open & hook','"Hold on / wait" self-interrupt',r'\b(?:hold on|wait|no, like|okay,? but)\b',M,'Narrator interrupts himself to correct scope or tone.','Use to re-scope a claim right after the hook.','Do not fake surprise repeatedly.','Does the interrupt narrow or sharpen the claim?')
a('Cold open & hook','Shock adjective framing',r'\b(?:insane|crazy|wild|terrifying|scary|absurd|unbelievable|shocking|disturbing)\b',O,'Emotional label on the event early.','Earn the adjective with a fact in the same breath.','No adjective without evidence.','Is each shock word followed by a fact?')
a('Cold open & hook','Title-promise restatement',r'\b(?:this is the story of|this video|in this video|today we|i want to tell you)\b',M,'Narrator states what the video is.','Say it plainly once, framed as a story.','No "In this video we will explore".','Is the promise phrased as a story, not a syllabus?')
a('Cold open & hook','Escalation ladder in open',r'\b(?:and now|and it\'s not just|not only|even|and then)\b',O,'Each open sentence raises the scale.','Go person -> community -> economy.','Do not peak in sentence one.','Does each open beat get bigger?')
# B. Characters
a('Character','Named person introduction',r'\b(?:this is|meet|named|a guy named|a man named|a woman named)\b',M,'Introduce a person by name with a hook detail.','Name + one vivid fact.','No CV dumps.','Does each new person get one memorable detail?')
a('Character','Character with a number',r'\b(?:\d+-year-old|\d+ years old|years old)\b',M,'Age/number pinned to a person.','Use ages and amounts to make people concrete.','Don\'t list ages for everyone.','Is the number relevant to stakes?')
a('Character','Ordinary-person proxy',r'\b(?:one guy|a guy|a trucker|a mom|a family|someone|a student|a worker|a dad|people like)\b',M,'An everyday person standing in for the viewer.','Use one ordinary person before the system.','No faceless "consumers".','Is there an ordinary human in the first third?')
a('Character','Powerful figure as character',r'\b(?:musk|altman|zuckerberg|bezos|trump|amodei|ceo|founder|billionaire)\b',M,'Big names treated as characters with motives.','Give them wants and contradictions.','Avoid pure hagiography or pure cartoon.','Does the figure want something specific?')
a('Character','Quoted character voice',r'\b(?:said|says|told|wrote|tweeted|posted)\b',M,'Characters speak through quotes.','Short, sharp quotes; frame them.','No long quote blocks without framing.','Is each quote framed by who and when?')
a('Character','Motive statement',r'\b(?:wanted|wants|wanted to|trying to|tried to|goal was|so that)\b',M,'What a character is after.','State motive before the action.','Do not leave actions unmotivated.','Can you say what each actor wants?')
a('Character','Contradiction in character',r'\b(?:same (?:guy|person|man|company)|ironically|despite|who once|used to)\b',M,'Show a character contradicting themselves.','Pair a past statement with a present act.','No unsupported hypocrisy charges.','Is the contradiction sourced?')
a('Character','Company as character',r'\b(?:openai|google|microsoft|nvidia|meta|amazon|apple|tesla|spacex|anthropic|xai)\b',M,'Institutions personified.','Give the company verbs (wants, panics, bets).','Do not treat companies as neutral background.','Does the company act?')
# C. Stakes
a('Stakes','Personal stakes to viewer',r'\b(?:your (?:job|money|rent|bill|phone|kids|life|data)|you (?:pay|will|could lose))\b',M,'Why it hits the viewer\'s life.','Tie the system back to the viewer\'s wallet or life.','Do not keep stakes abstract.','Is the viewer\'s stake stated by the 1st third?')
a('Stakes','Money stakes',r'\$\d|\b(?:billion|trillion|million) dollars\b|\b(?:billion|trillion)\b',M,'Amounts of money at stake.','Use exact figures with sources.','No "huge sums".','Is there an exact figure?')
a('Stakes','Existential stakes',r'\b(?:extinction|end of|destroy|collapse|kill|die|wipe out|catastroph)\w*',M,'Survival-level framing.','Use sparingly and with sources.','Do not escalate to apocalypse without evidence.','Is the apocalypse claim attributed?')
a('Stakes','Deadline / ticking clock',r'\b(?:by (?:20\d\d|next year|the end of)|within \d+|in \d+ (?:years|months|weeks|days)|running out)\b',M,'A time limit raises tension.','Name the deadline.','No fake urgency.','Is there a dated deadline?')
a('Stakes','Scale comparison',r'\b(?:more than|bigger than|as much as|the size of|equivalent to|times (?:more|bigger|larger))\b',M,'Compare to something graspable.','Use physical comparisons (cities, football fields).','No unanchored "massive".','Does each big number get a comparison?')
a('Stakes','Who pays',r'\b(?:who pays|you pay|taxpayers|consumers|workers|we pay|the bill)\b',M,'Name who absorbs the cost.','End systemic sections on who pays.','Do not leave cost abstract.','Is the payer named?')
# D. Tension & release
a('Tension','Complication pivot ("but")',r'^but\b',M,'A turn that complicates the last beat.','Turn every 3-5 sentences.','Avoid long runs of agreement.','Count turns per minute.')
a('Tension','The problem is',r'\bthe (?:problem|issue|catch|twist|kicker) (?:is|was|here)\b',M,'Name the complication explicitly.','Use as a section hinge.','Do not overuse as a tic.','Is each problem resolved or escalated?')
a('Tension','Release / plain answer',r'^(?:so|the answer|turns out|it turns out|and the answer)\b',M,'Release after tension with a plain answer.','Give the answer in one short line.','Do not bury the answer.','Is the answer under 15 words?')
a('Tension','Short punch line after long build',r'^[^,]{1,30}[.!]$',M,'A short sentence lands after long ones.','Follow a 30-word sentence with a 4-word one.','Do not make all sentences short.','Is there a short punch after a build?')
a('Tension','Contrast with expectation',r'\b(?:instead|but actually|in reality|the opposite|turns out)\b',M,'Reality vs expectation.','Set expectation first.','No contrast without setup.','Was the expectation stated?')
a('Tension','Escalation "and it gets worse"',r'\b(?:gets worse|it gets|even worse|but it doesn\'t stop|that\'s not all|on top of that)\b',M,'Signal another level down.','Use once per act.','Not every beat.','Is the new level genuinely worse?')
a('Tension','Suspense hedge "but here\'s"',r'\bhere\'s (?:the thing|what|where|why|how|the|a)\b',M,'Presenter line before a reveal.','Follow immediately with the reveal.','Do not stack two in a row.','Does the next sentence pay it?')
# E. Open loops
a('Open loops','Explicit come-back loop',r'\b(?:come back to|get to (?:that|this)|more on that|later|in a (?:second|minute|bit))\b',M,'Narrator flags a thread to pay later.','Pay every flagged loop.','Do not open loops you never close.','List loops; are all paid?')
a('Open loops','Unanswered question parked',r'\b(?:but why|so why|how did|what happened|what does that mean)\b.*\?$',M,'A question left hanging over a section.','Answer within ~2 minutes.','Do not answer immediately every time.','Is the gap 2+ sentences?')
a('Open loops','Teaser of a later reveal',r'\b(?:but that\'s not|that wasn\'t|little did|what (?:he|they|she) didn\'t know|it wouldn\'t be)\b',M,'Foreshadow a later turn.','Plant once per act.','No empty teasers.','Is the tease paid?')
a('Open loops','Numbered structure promise',r'\b(?:three|four|two|five) (?:reasons|things|problems|oil shocks|ways|parts|steps)\b',M,'Promise a count, creating loops.','Count down visibly.','Do not lose count.','Are all items delivered?')
a('Open loops','"To understand that" detour',r'\bto understand\b',M,'Rewind to explain before continuing.','Signal the detour.','No unsignaled time jumps.','Is the detour signalled and returned from?')
# F. Reveals
a('Reveals','"Turns out" reveal',r'\bturns? out\b',M,'Plain-speech reveal.','Reveal with a fact, not adjective.','Do not reveal what was obvious.','Is the reveal surprising and sourced?')
a('Reveals','Hidden actor reveal',r'\b(?:behind (?:it|this|the)|the real reason|secretly|quietly|it was actually)\b',M,'Reveal who is really behind it.','Build the clue trail first.','No conspiracy without evidence.','Were clues planted?')
a('Reveals','Number reveal',r'\b(?:that\'s|it\'s|which is) (?:about |over |more than |nearly |almost )?\$?\d',M,'A reveal delivered as a number.','Land the number at sentence end.','Do not pile 5 numbers in one sentence.','Is the number the last stressed word?')
a('Reveals','Document/evidence reveal',r'\b(?:report|study|document|filing|lawsuit|emails?|testimony|leaked|according to|data shows?)\b',M,'Evidence as reveal.','Name the document.','No "studies show".','Is the source named?')
a('Reveals','Research-frame reveal',r'\b(?:as i researched|when i (?:looked|dug|read)|i found|i realized|i discovered)\b',M,'Narrator discovering on our behalf.','Use first person discovery.','Do not overclaim personal research.','Is the discovery concrete?')
# G. Anecdotes & scene
a('Anecdote & scene','Micro-anecdote',r'\b(?:one (?:day|time|night|morning)|once|a few (?:years|months|weeks) ago|last (?:year|week|month))\b',M,'Small story unit.','Keep to 3-6 sentences with a turn.','No pointless anecdotes.','Does the anecdote change the argument?')
a('Anecdote & scene','Personal narrator anecdote',r'\b(?:i remember|when i was|my (?:dentist|friend|mom|dad|first thought)|i used to|i\'ve been)\b',M,'Narrator\'s own life as evidence.','Use one per video, early.','Do not center yourself throughout.','Is it relatable?')
a('Anecdote & scene','Place setting',r'\b(?:in (?:texas|california|michigan|china|taiwan|iran|arizona|virginia|new york|the desert|a small town)|a town|a city|a village)\b',M,'Naming a place.','Put the camera somewhere.','No placeless claims.','Is there a place per act?')
a('Anecdote & scene','Sensory/physical detail',r'\b(?:hot|loud|smell|noise|heat|water|dust|roar|hum|desert|concrete|glow)\b',M,'Physical texture.','One sensory detail per scene.','Do not overwrite.','Can you picture it?')
a('Anecdote & scene','"Here\'s a" footage pointer',r'^(?:here\'s|this is|look at|like this is)\b',M,'Narrator points at on-screen evidence.','Pair each with b-roll.','Do not point at nothing.','Is there footage for it?')
a('Anecdote & scene','Time jump marker',r'^(?:in (?:19|20)\d\d|by (?:19|20)\d\d|years later|a year later|months later|fast forward|back in)\b',M,'Move in time explicitly.','Announce jumps.','No silent jumps.','Is each jump marked?')
a('Anecdote & scene','Dated moment mid-story',r'\b(?:on (?:january|february|march|april|may|june|july|august|september|october|november|december) \d+|in (?:19|20)\d\d)\b',M,'Date-stamped beats throughout.','Date key beats.','Not every sentence.','Are turning points dated?')
# H. Narrator role
a('Narrator','Narrator opinion',r'\b(?:i think|i believe|in my opinion|i\'d argue|personally)\b',M,'Narrator states a view.','Own opinions as opinions.','No fake neutrality or preaching.','Are opinions flagged?')
a('Narrator','Narrator emotion',r'\b(?:i was|i\'m) (?:shocked|surprised|scared|worried|honestly|kind of|pretty|blown)\b|\bi can hardly believe\b',M,'Narrator reacts emotionally.','React once at the key reveal.','Not constant hype.','Is the reaction earned?')
a('Narrator','Narrator as guide ("let\'s")',r'\blet\'s\b|\blet me\b',M,'Guiding the viewer through.','Use at section hinges.','No tour-guide overuse.','Does each "let\'s" start a section?')
a('Narrator','Honesty/candor marker',r'\b(?:honestly|to be fair|to be clear|i have to be honest|i\'ll be honest|truth is)\b',M,'Signals sincerity or fairness.','Use before a fair counterpoint.','Not as a filler tic.','Does a fair point follow?')
a('Narrator','Narrator uncertainty',r'\b(?:we don\'t know|nobody knows|no one knows|it\'s unclear|i\'m not sure|hard to say)\b',M,'Admit what is unknown.','Admit limits.','No false certainty.','Are unknowns flagged?')
a('Narrator','Team/we narrator',r'\b(?:we warned|we covered|we made a video|we talked about|our team|we reached out)\b',M,'Channel voice as "we".','Reference past coverage.','Do not over-promote.','Is the callback relevant?')
a('Narrator','Viewer-direct address',r'^(?:you|if you|imagine)\b',M,'Talking straight to the viewer.','Second person at stakes beats.','No lecturing.','Is "you" used at stakes beats?')
# I. Structure & pacing
a('Structure','Section hinge "So"',r'^so\b',M,'"So" moves to the next beat.','Use at transitions.','Not every sentence.','Do hinges coincide with topic shifts?')
a('Structure','"Now" hinge',r'^now\b',M,'Time/topic pivot.','Use to bring back to present.','No overuse.','Does "Now" move time or topic?')
a('Structure','Re-explanation "in other words"',r'\b(?:in other words|basically|put simply|simply put|think of it like|it\'s like)\b',M,'Restate in plain terms.','Follow jargon with plain restatement.','Do not restate the obvious.','Is every jargon term restated?')
a('Structure','Analogy',r'\b(?:it\'s like|think of it|imagine|kind of like|the equivalent of|like a)\b',M,'Concrete analogy.','One per mechanism.','No mixed metaphors.','Is the analogy physical?')
a('Structure','Mechanism chain "which means"',r'\b(?:which means|that means|which is why|and that\'s why|so that)\b',M,'Cause-effect cascades.','Chain 2-3 consequences.','Do not leap steps.','Can each link be checked?')
a('Structure','Recap line',r'\b(?:so to recap|in short|so basically|long story short|so yeah)\b',M,'Mini summary.','Recap at act ends.','No essay "in summary".','Is the recap spoken?')
a('Structure','List cadence ("first... second")',r'^(?:first|second|third|the first|the second|the third|one is|another)\b',M,'Enumerated beats.','Keep lists short.','No slide-deck listing.','Are items parallel?')
a('Structure','Rhetorical Q then answer',r'\?$',M,'Ask, then answer next line.','Answer immediately in short form.','No unanswered rhetorical spam.','Is the next line the answer?')
# J. Antagonists
a('Antagonist','Named villain/antagonist',r'\b(?:greed|monopoly|lobby|cartel|regulators?|wall street|big tech|corporations|private equity|opec)\b',M,'A force or actor opposing interests.','Make the system the villain, with faces.','No cartoon villains.','Is the antagonist\'s motive given?')
a('Antagonist','Blame attribution',r'\b(?:because of|blame|fault|responsible for|caused by|thanks to)\b',M,'Assign cause.','Attribute with evidence.','No vague "they".','Is blame sourced?')
a('Antagonist','Hypocrisy beat',r'\b(?:while|at the same time|meanwhile)\b.*\b(?:paid|made|earned|bought|raised|profit)',M,'Contrast suffering with profiting.','Juxtapose two facts.','Do not moralize.','Are both facts sourced?')
a('Antagonist','Warning voices',r'\b(?:warned|warning|alarm|whistleblower|critics?|experts? (?:say|warn))\b',M,'People who saw it coming.','Cite them by name.','No "experts say".','Are warners named?')
# K. Irony & humor
a('Irony & humor','Dry irony beat',r'\b(?:ironically|of course|naturally|which is great|great\.|nice bit|funny thing|the funny part)\b',M,'Dry understatement or irony.','Deadpan after a big fact.','No winking every line.','Is the irony one line?')
a('Irony & humor','Joke/aside',r'\b(?:joke|lol|by the way|fun fact|side note|anyway)\b',M,'Narrator aside.','Use to reset tension.','Do not derail.','Does it return to thread?')
a('Irony & humor','Pop-culture reference',r'\b(?:simpsons|movie|sci-fi|terminator|netflix|marvel|meme|game of thrones|black mirror)\b',M,'Cultural shorthand.','One per video.','No dated meme spam.','Will the audience get it?')
a('Irony & humor','Understatement',r'\b(?:not great|not ideal|a bit|a little|kind of a problem|slightly)\b',M,'Undersell for effect.','Use after a dire fact.','Not on tragedy involving victims.','Is it after a big fact?')
a('Irony & humor','Profanity for emphasis',r'\b(?:hell|damn|shit|fuck\w*)\b',M,'Swearing as emphasis.','Rare, at peak frustration (Gen).','Never in Adam-lean.','Is it once at most?')
# L. Emotional turns
a('Emotion','Fear beat',r'\b(?:scary|terrifying|afraid|fear|worried|panic|dangerous)\b',M,'Fear framing.','Pair with evidence.','No fear-mongering.','Is the fear sourced?')
a('Emotion','Empathy beat',r'\b(?:imagine being|families|victims|lost (?:his|her|their)|struggling|can\'t afford)\b',M,'Human cost.','Show one person\'s cost.','Do not exploit.','Is the person respected?')
a('Emotion','Anger/outrage beat',r'\b(?:outrage|furious|angry|insane|ridiculous|absurd|unacceptable)\b',M,'Moral heat.','Let facts make the anger.','No ranting.','Is anger tied to a fact?')
a('Emotion','Hope/agency beat',r'\b(?:hope|good news|the good news|can do|we can|there\'s still|solution|fix)\b',M,'Turn toward agency.','Land on a realistic hope.','No fake happy endings.','Is the hope concrete?')
a('Emotion','Awe/wonder beat',r'\b(?:incredible|amazing|remarkable|mind-blowing|astonishing|beautiful)\b',M,'Wonder at scale.','Use for genuine scale.','Not for marketing.','Is it about scale?')
# M. Zoom
a('Zoom','Personal-to-systemic zoom',r'\b(?:and it\'s not just|this isn\'t just|it\'s happening (?:all over|everywhere)|across the country|around the world|entire (?:industry|economy|country))\b',M,'From one case to the whole system.','Zoom out after an anecdote.','Do not stay micro.','Is there a zoom-out after the anecdote?')
a('Zoom','Systemic-to-personal zoom',r'\b(?:for you|for most people|for the average|what this means for you|your (?:bill|rent|job))\b',M,'Back from system to viewer.','Zoom back in at the end of acts.','Do not end abstract.','Does each act end on a person?')
a('Zoom','Historical zoom-out',r'\b(?:history|historically|for decades|for centuries|since the|ever since|back in the)\b',M,'Long-time context.','Brief history, then present.','No textbook history.','Is history under ~15% of runtime?')
a('Zoom','Global zoom',r'\b(?:world|global|globally|planet|every country|countries)\b',M,'Planet scale.','Earn it with steps.','No sudden jumps.','Were steps shown?')
# N. Payoffs & callbacks
a('Payoff & callback','Callback to open',r'\b(?:remember (?:that|when|how|the)|like i said|as i (?:said|mentioned)|back to)\b',M,'Return to something earlier.','Call back the cold-open image at the end.','Do not call back trivia.','Does the end echo the open?')
a('Payoff & callback','Loop payoff',r'\b(?:that\'s (?:why|where|what|how)|and that\'s|this is why|which brings us)\b',M,'Paying off a planted question.','Pay with a "that\'s why" line.','No unpaid loops.','Is each loop paid?')
a('Payoff & callback','Final reveal/twist',r'\b(?:turns out|the real|actually|in the end)\b',E,'Last-act twist.','Save one twist for the last act.','No twist without setup.','Was it seeded?')
# O. Endings
a('Ending','Soft close / thanks',r'\b(?:thanks for watching|thank you|see you|subscribe|let me know|comment)\b',E,'Spoken sign-off.','Keep sign-off short.','No long outro.','Is it < 3 sentences?')
a('Ending','Open-question ending',r'\?$',E,'End on a question for the viewer.','One real question.','No cliché "only time will tell".','Is the question specific?')
a('Ending','Moral/implication ending',r'\b(?:the lesson|what this means|the question is|the real question|at the end of the day)\b',E,'Implication line.','State implication plainly.','No preachy summary.','Is it one line?')
a('Ending','Sponsor/CTA transition',r'\b(?:sponsor|brought to you|link (?:in|below)|patreon|newsletter|check out)\b',M,'Ad or CTA segment.','Bridge from story stakes to the ad.','No abrupt ad drops.','Is the bridge topical?')
a('Ending','Future projection ending',r'\b(?:will|going to|in the future|next (?:year|decade)|by 20\d\d)\b',E,'Project forward.','Name what to watch.','No vague futurism.','Is there a dated next step?')
# P. Evidence & credibility
a('Evidence','Named source',r'\b(?:according to|reported|reports?|the (?:new york times|wall street journal|guardian|bloomberg|reuters|ft|financial times)|study|survey)\b',M,'Attributed claims.','Name the outlet.','No "sources say".','Is every big claim attributed?')
a('Evidence','Exact percentage',r'\d+ ?%|\bpercent\b',M,'Percentages.','Round sensibly, attribute.','No fake precision.','Is it attributed?')
a('Evidence','Expert quote framing',r'\b(?:professor|researcher|scientist|analyst|economist|expert|former)\b',M,'Expert introduced.','Title + name + claim.','No anonymous experts.','Name and title?')
a('Evidence','Counterpoint/steelman',r'\b(?:to be fair|on the other hand|in fairness|some argue|critics|that said)\b',M,'Fair counterargument.','One steelman per video.','No strawman.','Is it the strongest counter?')
# Q. Language-story interface
a('Spoken texture','Self-correction mid-line',r'\b(?:or rather|well,|i mean|no, |actually,)\b',M,'Narrator revises live.','Use once or twice.','No fake stumbles.','Does it sharpen the claim?')
a('Spoken texture','Second-person hypothetical',r'\b(?:if you|say you|let\'s say|imagine you)\b',M,'Put viewer in a scenario.','Use for mechanisms.','No long hypotheticals.','Is it under 4 sentences?')
a('Spoken texture','Concrete brand/product names',r'\b(?:photoshop|iphone|chatgpt|starlink|tesla|amazon|walmart|netflix|word|excel|grok|claude)\b',M,'Specific products.','Name real products.','No "a popular app".','Are products named?')
a('Spoken texture','Repetition for emphasis',r'\b(\w{4,})\b.*\b\1\b.*\b\1\b',M,'Same word repeated in a sentence.','Use deliberately.','Not accidental.','Is it intentional?')
# R. More hooks/structure
a('Structure','Act break question',r'^(?:so|but) (?:what|why|how|where|who)\b.*\?$',M,'Question that opens a new act.','Open acts with questions.','Not every paragraph.','Does an act begin here?')
a('Structure','"Here\'s why" bridge',r'\bhere\'s why\b|\band here\'s\b',M,'Bridge into explanation.','Use before mechanisms.','No overuse.','Does a mechanism follow?')
a('Structure','"The story starts" origin',r'\b(?:it (?:all )?(?:started|began)|the story (?:starts|begins)|this all started|origins?)\b',M,'Origin-story entry.','Mark the origin clearly.','No long preambles.','Is the origin dated?')
a('Structure','Present-tense immediacy',r'\b(?:right now|today|this week|as we speak|currently)\b',M,'Now-ness.','Anchor stakes in now.','Not empty "today".','Is "now" dated?')
a('Reveals','Comparison reveal (X vs Y)',r'\b(?:compared to|versus|vs\.?|while .* only)\b',M,'Reveal by contrast.','Two numbers side by side.','No apples to oranges.','Are units same?')
a('Tension','Cliffhanger sentence',r'\b(?:and that\'s when|that\'s when|until|then something)\b',M,'Hook into next beat.','End sections on one.','Not mid-explanation.','Does next section open on payoff?')
a('Character','Underdog framing',r'\b(?:small|tiny|nobody|unknown|a kid|a student|startup|out of nowhere)\b',M,'Small vs big.','Pit small against big.','No fake underdogs.','Is size difference real?')
a('Character','Victim framing',r'\b(?:victims?|harmed|hurt|lost (?:everything|their|his|her)|evicted|laid off|fired)\b',M,'People harmed.','Name the harm concretely.','No exploitation.','Is the harm specific?')
a('Stakes','Irreversibility',r'\b(?:no going back|can\'t undo|permanent|forever|irreversible|too late)\b',M,'Stakes that can\'t be reversed.','Use at the end of act 2.','Not every act.','Is it argued?')
a('Emotion','Relief/comic reset',r'\b(?:okay|anyway|so yeah|alright|fine)\b',M,'Reset after heavy beat.','Use after a dark beat.','Not mid-tension.','Did tension just peak?')
a('Narrator','Viewer agreement check',r'\b(?:right\?|makes sense|you get it|you see|see\?)\b',M,'Checks in with viewer.','Use after a mechanism.','Not every line.','Was a mechanism just explained?')
a('Zoom','Money-trail zoom',r'\b(?:follow the money|who profits|where the money|the money goes)\b',M,'Track money.','Follow one dollar.','No vague greed.','Is the flow traced?')
